import bmesh
# Helpers create only within the combined Craft collection.
def geom(name,verts,faces,mat,uvs=None):
 me=bpy.data.meshes.new(name);me.from_pydata(verts,[],faces);me.materials.append(mat);me.update()
 ob=bpy.data.objects.new(name,me);c.objects.link(ob)
 if uvs is not None:
  uv=me.uv_layers.new(name='MetricSheetAtlas')
  for p in me.polygons:
   for li in p.loop_indices:uv.data[li].uv=uvs[me.loops[li].vertex_index]
 return ob
def atlas(k,u,v):return ((k%4+(8+max(0,min(1,u))*(TW-16))/TW)/4,(k//4+(8+max(0,min(1,v))*(TH-16))/TH)/4)
def metric_uv(ob,scale=1.4):
 for layer in list(ob.data.uv_layers):ob.data.uv_layers.remove(layer)
 uv=ob.data.uv_layers.new(name='MetricFittingUV')
 for p in ob.data.polygons:
  axis=max(range(3),key=lambda a:abs(p.normal[a]));a,b=([1,2] if axis==0 else [0,2] if axis==1 else [0,1])
  for li in p.loop_indices:
   q=ob.matrix_world@ob.data.vertices[ob.data.loops[li].vertex_index].co;uv.data[li].uv=(q[a]/scale,q[b]/scale)
def hardbox(name,pos,size,mat=None,bevel=.002):
 old['c']=c;ob=old['box'](name,pos,size,mat or forged,bevel);metric_uv(ob);return ob
def rod(name,p0,p1,r=.022,mat=None,sides=8):
 old['c']=c;ob=old['cylinder'](name,p0,p1,r,mat or forged,sides);return ob
def screw(name,p,axis):
 p=Vector(p);n=Vector(axis).normalized()
 rod(name+' washer',p,p+n*.007,.031,forged,12)
 rod(name+' hex',p+n*.006,p+n*.021,.018,forged,6)
def skin(name,us,vs,point,normal_out,k,uvfunc):
 verts=[];uvs=[]
 for vv in vs:
  for uu in us:verts.append(point(uu,vv));uvs.append(atlas(k,*uvfunc(uu,vv)))
 faces=[];nu=len(us)
 for j in range(len(vs)-1):
  for i in range(nu-1):
   a=j*nu+i;face=(a,a+1,a+1+nu,a+nu)
   N=(Vector(verts[a+1])-Vector(verts[a])).cross(Vector(verts[a+nu])-Vector(verts[a]))
   if N.dot(Vector(normal_out))<0:face=tuple(reversed(face))
   faces.append(face)
 ob=geom(name,verts,faces,sheet,uvs)
 for p in ob.data.polygons:p.use_smooth=True
 so=ob.modifiers.new('steel sheet thickness 4mm','SOLIDIFY');so.thickness=.004;so.offset=-1
 return ob
def roof_z(xx):return 6.96-abs(xx)*.52
PW=.864;roof_front=2.62
# Clipped sheet fragments retain their parent panel UV; skylights stay true openings.
def make_roof(side):
 for col in range(7):
  y0=roof_front+col*PW;y1=y0+PW+.025;k=(col+(0 if side>0 else 3))%8
  yc=sorted(set([y0,y1]+[a for a in [3.85,5.05,6.25,7.45] if y0<a<y1]))
  for xa,xb in [(0,1.1),(1.1,2.18),(2.16,2.8),(2.8,4.08)]:
   for ya,yb in zip(yc[:-1],yc[1:]):
    mid=(ya+yb)*.5
    if side>0 and 1.099<xa and xb<2.801 and (3.85<mid<5.05 or 6.25<mid<7.45):continue
    us=np.linspace(ya,yb,max(3,int((yb-ya)/.018)+1)).tolist();vs=np.linspace(xa,xb,max(2,int((xb-xa)/.4)+1)).tolist()
    def point(yy,dd):
     # Wide low dents affect the sheet locally; rolled ribs remain straight and taut.
     wave=.020*math.cos((yy-roof_front)*math.tau/.144)
     dent=-.012*math.exp(-((dd-3.25)/.52)**2-((yy-(y0+.47))/.19)**2) if col in [1,5] else 0
     lap=.009 if dd<2.18 else 0
     return (side*dd,yy,roof_z(dd)+wave+dent+lap)
    skin('Steel roof panel %s %02d'%(side,col),us,vs,point,(side*.52,0,1),k,lambda yy,dd:((yy-y0)/(PW+.025),1-dd/4.08))
  for dd in [.18,1.02,2.16,3.90]:
   for yy in [y0+.072,y0+.504]:
    if side>0 and 1.1<dd<2.8 and (3.85<yy<5.05 or 6.25<yy<7.45):continue
    screw('Steel roof fixing',(side*dd,yy,roof_z(dd)+.032),(side*.52,0,1))
 # Eave folded L flashing is thin steel, with a turned drip edge.
 y0=roof_front-.02;y1=roof_front+7*PW+.04;x=side*4.09;z=roof_z(4.09)
 verts=[(x-side*.10,y0,z+.018),(x,y0,z+.018),(x,y0,z-.135),(x+side*.018,y0,z-.155),(x-side*.10,y1,z+.018),(x,y1,z+.018),(x,y1,z-.135),(x+side*.018,y1,z-.155)]
 ob=geom('Steel folded eave flashing '+str(side),verts,[(0,4,5,1),(1,5,6,2),(2,6,7,3)],forged);metric_uv(ob)
 so=ob.modifiers.new('folded sheet edge','SOLIDIFY');so.thickness=.006
# Vertical wall panels retain existing openings; v points upward for rust runs.
def wall_panel(name,a,b,z0,z1,plane,axis,side,k):
 us=np.linspace(a,b,max(3,int((b-a)/.018)+1)).tolist();vs=np.linspace(z0,z1,max(2,int((z1-z0)/.35)+1)).tolist()
 def point(q,z):
  w=.015*math.cos(q*math.tau/.144)
  return (q,plane+side*w,z) if axis=='x' else (plane+side*w,q,z)
 normal=(0,side,0) if axis=='x' else (side,0,0)
 ob=skin(name,us,vs,point,normal,k,lambda q,z:((q-a)/(b-a),(z-z0)/(z1-z0)))
 for q in [a+.07,b-.07]:
  for z in [z0+.12,z1-.12]:
   p=Vector(point(q,z))+Vector(normal)*.008;screw('Steel wall fixing',p,normal)
 return ob
# First sample: right roof, right front siding and one real metal threshold/fascia junction.
removed=[]
for ob in list(c.objects):
 n=ob.get('source_component','')
 co=[ob.matrix_world@Vector(v) for v in ob.bound_box]
 if (n.startswith(('B old roof sheet','B folded sheet seam','B eave edge')) and min(p.x for p in co)>-.01) or (n.startswith('B facade plank') and min(p.x for p in co)>1.4):
  removed.append(ob.name);bpy.data.objects.remove(ob,do_unlink=True)
make_roof(1)
for i,(a,b) in enumerate([(1.48,2.23),(2.21,2.97),(2.95,3.73)]):wall_panel('Steel facade sample '+str(i),a,b,1.60,3.77,2.945,'x',-1,8+i)
# Thin folded reveal covers the panel edge, leaving the existing doorway dimensions.
hardbox('Steel sample jamb return',(1.44,2.92,2.68),(.085,.13,2.18))
for z in [1.80,2.70,3.58]:screw('Steel jamb fixing',(1.44,2.843,z),(0,-1,0))
